import {
  Group,
  Mesh,
  MeshPhysicalMaterial,
  MeshBasicMaterial,
  CylinderGeometry,
  OctahedronGeometry,
  PlaneGeometry,
  DirectionalLight,
  Color,
  CanvasTexture,
  DoubleSide,
  MathUtils,
} from 'three/webgpu';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import textUtils from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();
  root.position.set(
    config.position?.[0] ?? 0,
    config.position?.[1] ?? 0,
    config.position?.[2] ?? 0
  );
  root.rotation.set(
    config.rotation?.[0] ?? 0,
    config.rotation?.[1] ?? 0,
    config.rotation?.[2] ?? 0
  );
  root.scale.set(
    config.scale?.[0] ?? 1,
    config.scale?.[1] ?? 1,
    config.scale?.[2] ?? 1
  );

  // ----- Prism -----
  const side = 1.2;
  const radius = side / Math.sqrt(3);
  const prismGeom = new CylinderGeometry(radius, radius, 1.8, 3, 1, false);
  const prismMat = new MeshPhysicalMaterial({
    transmission: 1.0,
    thickness: 0.9,
    ior: 1.55,
    roughness: 0.08,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    attenuationColor: new Color('#e8ecf2'),
    attenuationDistance: 2.5,
    iridescence: 1.0,
    iridescenceIOR: 1.3,
    iridescenceThicknessRange: [120, 480],
    color: new Color('#0b0b10'),
  });
  const prismMesh = new Mesh(prismGeom, prismMat);
  prismMesh.rotation.set(
    0,
    MathUtils.degToRad(20),
    MathUtils.degToRad(12)
  );
  root.add(prismMesh);

  // ----- Emissive Core -----
  const coreGeom = new OctahedronGeometry(0.35);
  const coreMat = new MeshPhysicalMaterial({
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38'),
    emissiveIntensity: 2.2,
  });
  const coreMesh = new Mesh(coreGeom, coreMat);
  root.add(coreMesh);

  // ----- Rim Light -----
  const rimLight = new DirectionalLight(new Color('#e8ecf2'), 1.5);
  rimLight.position.set(-2, 1, -2);
  root.add(rimLight);

  // ----- Caustic Plane -----
  const planeGeom = new PlaneGeometry(2.4, 0.5);
  planeGeom.rotateX(-Math.PI / 2);
  const canvas = new OffscreenCanvas(256, 1);
  const ctx2d = canvas.getContext('2d');
  const grad = ctx2d.createLinearGradient(0, 0, 256, 0);
  grad.addColorStop(0.2, '#ff2a38');
  grad.addColorStop(0.5, '#e8ecf2');
  grad.addColorStop(0.8, '#9fb0c4');
  ctx2d.fillStyle = grad;
  ctx2d.fillRect(0, 0, 256, 1);
  const causticTex = new CanvasTexture(canvas);
  causticTex.needsUpdate = true;
  const planeMat = new MeshBasicMaterial({
    map: causticTex,
    transparent: true,
    opacity: 0.35,
    side: DoubleSide,
    depthWrite: false,
  });
  const causticPlane = new Mesh(planeGeom, planeMat);
  causticPlane.position.set(0, -1.1, 0);
  root.add(causticPlane);

  // ----- Text: Headline -----
  const headline = ctx.fontAtlas.createTextMesh({
    text: 'Light, machined.',
    style: {
      family: 'Lora',
      size: 68,
      weight: 600,
      letterSpacing: -0.005,
      lineHeight: 1.1,
      color: '#e8ecf2',
    },
    atlas: { index: 0, sourceRect: [0, 0, 512, 320] },
  });
  if (headline) {
    headline.position.set(0, -1.75, 0);
    root.add(headline);
  }

  // ----- Text: Caption -----
  const caption = ctx.fontAtlas.createTextMesh({
    text: 'SAPPHIRE OVER DIAL / ZERO DISTORTION',
    style: {
      family: 'JetBrains Mono',
      size: 18,
      weight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: '#e8ecf2',
    },
    atlas: { index: 0, sourceRect: [0, 0, 512, 320] },
  });
  if (caption) {
    caption.position.set(0, -2.25, 0);
    root.add(caption);
  }

  // ----- Apply Cinematic Primitives -----
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  // ----- Cleanup ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    prismGeom.dispose();
    prismMat.dispose();
    coreGeom.dispose();
    coreMat.dispose();
    planeGeom.dispose();
    planeMat.map?.dispose();
    planeMat.dispose();
    causticTex.dispose();
    if (headline) {
      headline.traverse((obj) => {
        if (obj.isMesh) {
          obj.geometry?.dispose();
          obj.material?.dispose();
        }
      });
    }
    if (caption) {
      caption.traverse((obj) => {
        if (obj.isMesh) {
          obj.geometry?.dispose();
          obj.material?.dispose();
        }
      });
    }
    if (root.userData.tl) {
      root.userData.tl.kill();
    }
  };

  return root;
}
